import{_ as e,o as _,c as t,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-010.Crfv3PyN.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/88-东京本地以外的人难以进入上流阶层.md","filePath":"books/xialiu-shehui/88-东京本地以外的人难以进入上流阶层.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/88-东京本地以外的人难以进入上流阶层.md"};function i(r,a,l,n,d,c){return _(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="东京本地以外的人难以进入上流阶层" tabindex="-1">东京本地以外的人难以进入上流阶层 <a class="header-anchor" href="#东京本地以外的人难以进入上流阶层" aria-label="Permalink to &quot;东京本地以外的人难以进入上流阶层&quot;">​</a></h2><p>接着我们再根据“欲求调查”的结果，来看看出生于不同地方的人的阶层意识有何差别（见表8-3）。这部分调查选取的样本数量比较少，所以也权作参考。</p><p>表8-3　出生于不同地方的团块次代的阶层意识</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>出生于横滨市和川崎市的团块次代男性，属于上流阶层的较多。可以说在横滨或川崎出生并且现在仍然居住在那里的男性，具有较高的阶层意识。</p><p>此外，出生于东京都23区的人属于上流阶层的不多，而出生在三多摩地区的人绝大多数属于下流阶层，个中的原因却无从知晓。</p><p>另一方面，出生于首都圈一都三县的团块次代的女性大约有两成左右属于上流阶层，但出生于东京以外的属上流阶层者就非常少。对于女性来说，出生于东京一都三县似乎有助于她们的阶层意识高扬。</p><p>但是，出生于东京之外的地方的女性，属于下流阶层的却很少。这可以解释为能够特地把女儿从其他地方送到东京来，这样的家庭无疑具有一定的经济实力。或许她们在当地本属于上流阶层，来到东京后就成了中流阶层。</p><p>综上所述，可以肯定的是在东京郊外，特别是横滨市、川崎市出生并长大的这个背景，对于现在的团块次代的阶层意识有着正面影响。可以说以东急田园都市线沿线地区为中心的第四山手圈，正在逐渐演变为团块次代的上流社区。</p>',10)])])}const m=e(p,[["render",i]]);export{h as __pageData,m as default};
